import sqlite3
import os
from contextlib import contextmanager
from flask import Flask, request, redirect, url_for, render_template, flash

app = Flask(__name__)
app.secret_key = os.environ.get("SECRET_KEY", os.urandom(24))

DB_PATH = os.environ.get("DB_PATH", "workshop.db")
MAX_SEATS = 20

def init_db():
    with sqlite3.connect(DB_PATH) as conn:
        conn.executescript("""
            PRAGMA journal_mode=WAL;
            CREATE TABLE IF NOT EXISTS seats (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT NOT NULL UNIQUE COLLATE NOCASE,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
        """)

@contextmanager
def get_db():
    conn = sqlite3.connect(DB_PATH, isolation_level=None, timeout=10)
    try:
        yield conn
    finally:
        conn.close()

def try_book_seat(name, email):
    """
    Atomically claim a seat. Returns (success, message).
    Uses BEGIN IMMEDIATE to acquire a write lock before counting,
    preventing concurrent sign-ups from exceeding MAX_SEATS.
    Unique constraint on email (NOCASE) prevents duplicate sign-ups.
    """
    with get_db() as conn:
        try:
            conn.execute("BEGIN IMMEDIATE")
            count = conn.execute("SELECT COUNT(*) FROM seats").fetchone()[0]
            if count >= MAX_SEATS:
                conn.execute("ROLLBACK")
                return False, "Sorry, all 20 seats are taken."
            try:
                conn.execute(
                    "INSERT INTO seats (name, email) VALUES (?, ?)",
                    (name.strip(), email.strip().lower()),
                )
            except sqlite3.IntegrityError:
                conn.execute("ROLLBACK")
                return False, "This email has already registered."
            conn.execute("COMMIT")
            return True, "You're in! Your seat is reserved."
        except Exception:
            try:
                conn.execute("ROLLBACK")
            except Exception:
                pass
            raise

@app.route("/", methods=["GET", "POST"])
def index():
    if request.method == "POST":
        name = (request.form.get("name") or "").strip()
        email = (request.form.get("email") or "").strip()
        if not name or not email or "@" not in email:
            flash("Please enter a valid name and email.", "error")
            return redirect(url_for("index"))

        ok, msg = try_book_seat(name, email)

        with get_db() as conn:
            taken = conn.execute("SELECT COUNT(*) FROM seats").fetchone()[0]
        seats_left = MAX_SEATS - taken
        return render_template(
            "result.html",
            ok=ok, message=msg,
            taken=taken, seats_left=seats_left, max_seats=MAX_SEATS,
        )

    with get_db() as conn:
        taken = conn.execute("SELECT COUNT(*) FROM seats").fetchone()[0]
    seats_left = MAX_SEATS - taken
    return render_template(
        "index.html",
        taken=taken, seats_left=seats_left, max_seats=MAX_SEATS,
    )

if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=5000)
```

